"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[1731],{39382(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2026/06/11/cve-2026-49328","metadata":{"permalink":"/zh-cn/blog/2026/06/11/cve-2026-49328","editUrl":"https://github.com/apache/fesod/edit/main/website/i18n/zh-cn/docusaurus-plugin-content-blog/2026-06-11-cve-2026-49328.md","source":"@site/i18n/zh-cn/docusaurus-plugin-content-blog/2026-06-11-cve-2026-49328.md","title":"CVE-2026-49328 - Apache Fesod (Incubating): \u5bf9\u7528\u6237\u63d0\u4f9b\u7684URL\u9a8c\u8bc1\u4e0d\u5f53\u5bfc\u81f4SSRF\u6f0f\u6d1e","description":"\u5173\u4e8e CVE-2026-49328 \u7684\u5b89\u5168\u901a\u544a.","date":"2026-06-11T00:00:00.000Z","tags":[{"inline":true,"label":"announcement","permalink":"/zh-cn/blog/tags/announcement"},{"inline":true,"label":"security","permalink":"/zh-cn/blog/tags/security"},{"inline":true,"label":"CVE-2026-49328","permalink":"/zh-cn/blog/tags/cve-2026-49328"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"CVE-2026-49328 - Apache Fesod (Incubating): \u5bf9\u7528\u6237\u63d0\u4f9b\u7684URL\u9a8c\u8bc1\u4e0d\u5f53\u5bfc\u81f4SSRF\u6f0f\u6d1e","description":"\u5173\u4e8e CVE-2026-49328 \u7684\u5b89\u5168\u901a\u544a.","tags":["announcement","security","CVE-2026-49328"]},"unlisted":false,"nextItem":{"title":"\u4f7f\u7528 OpenRewrite \u4ece FastExcel 1.3.0 \u81ea\u52a8\u8fc1\u79fb\u5230 Apache Fesod (Incubating)","permalink":"/zh-cn/blog/2026/05/07/migration-from-fastexcel-with-openrewrite"}},"content":"\u5173\u4e8e Apache Fesod (Incubating) \u4e2d\u670d\u52a1\u5668\u7aef\u8bf7\u6c42\u4f2a\u9020\uff08SSRF\uff09\u6f0f\u6d1e **CVE-2026-49328** \u7684\u5b89\u5168\u901a\u544a\u3002\\n\\n\x3c!--truncate--\x3e\\n\\n## \u6f0f\u6d1e\u63cf\u8ff0\\n\\nApache Fesod (Incubating) \u7684 `fesod-sheet` \u6a21\u5757\u4e2d `UrlImageConverter` \u7ec4\u4ef6\u5b58\u5728\u670d\u52a1\u5668\u7aef\u8bf7\u6c42\u4f2a\u9020\uff08SSRF\uff09\u6f0f\u6d1e\u3002\u653b\u51fb\u8005\u53ef\u4ee5\u901a\u8fc7\u63d0\u4f9b\u6076\u610f\u7684\u56fe\u7247 URL\uff0c\u8bf1\u4f7f\u7cfb\u7edf\u5411\u5185\u90e8\u7f51\u7edc\u6216\u5176\u4ed6\u53d7\u9650\u8d44\u6e90\u53d1\u8d77\u51fa\u7ad9\u7f51\u7edc\u8bf7\u6c42\u3002\\n\\n## \u53d7\u5f71\u54cd\u7684\u6a21\u5757\u4e0e\u7248\u672c\\n\\nFesod Spreadsheet (`fesod-sheet`):\\n\\n- 2.0.1-incubating\\n\\n## \u4fee\u590d\u5efa\u8bae\\n\\n\u5efa\u8bae\u53d7\u5f71\u54cd\u7248\u672c\u7684\u7528\u6237\u5c3d\u5feb\u5347\u7ea7\u5230\u5bf9\u5e94\u7684\u4fee\u590d\u7248\u672c\u3002\\n\\n| \u53d7\u5f71\u54cd\u7248\u672c            | \u4fee\u590d\u7248\u672c             |\\n|------------------|------------------|\\n| 2.0.1-incubating | 2.0.2-incubating |\\n\\n## \u53c2\u8003\u94fe\u63a5\\n\\n- [https://github.com/apache/fesod/pull/917](https://github.com/apache/fesod/pull/917)\\n- [https://github.com/apache/fesod/releases/tag/2.0.2-incubating](https://github.com/apache/fesod/releases/tag/2.0.2-incubating)\\n- [https://fesod.apache.org/docs/download](https://fesod.apache.org/docs/download)\\n- [https://lists.apache.org/thread/c1pb5b66h02p9tlrnfbwcgcz85v16fkj](https://lists.apache.org/thread/c1pb5b66h02p9tlrnfbwcgcz85v16fkj)"},{"id":"/2026/05/07/migration-from-fastexcel-with-openrewrite","metadata":{"permalink":"/zh-cn/blog/2026/05/07/migration-from-fastexcel-with-openrewrite","editUrl":"https://github.com/apache/fesod/edit/main/website/i18n/zh-cn/docusaurus-plugin-content-blog/2026-05-07-migration-from-fastexcel-with-openrewrite.md","source":"@site/i18n/zh-cn/docusaurus-plugin-content-blog/2026-05-07-migration-from-fastexcel-with-openrewrite.md","title":"\u4f7f\u7528 OpenRewrite \u4ece FastExcel 1.3.0 \u81ea\u52a8\u8fc1\u79fb\u5230 Apache Fesod (Incubating)","description":"\u5c06 FastExcel 1.3 \u8fc1\u79fb\u81f3 Apache Fesod (Incubating) 2.0.1-incubating","date":"2026-05-07T00:00:00.000Z","tags":[{"inline":true,"label":"migration","permalink":"/zh-cn/blog/tags/migration"},{"inline":true,"label":"fastexcel","permalink":"/zh-cn/blog/tags/fastexcel"},{"inline":true,"label":"fesod","permalink":"/zh-cn/blog/tags/fesod"}],"hasTruncateMarker":true,"authors":[{"name":"Jing Yang","url":"https://github.com/bengbengbalabalabeng","socials":{"github":"https://github.com/bengbengbalabalabeng"},"imageURL":"data:image/png;base64,","key":"bengbengbalabalabeng","page":null}],"frontMatter":{"title":"\u4f7f\u7528 OpenRewrite \u4ece FastExcel 1.3.0 \u81ea\u52a8\u8fc1\u79fb\u5230 Apache Fesod (Incubating)","description":"\u5c06 FastExcel 1.3 \u8fc1\u79fb\u81f3 Apache Fesod (Incubating) 2.0.1-incubating","authors":["bengbengbalabalabeng"],"tags":["migration","fastexcel","fesod"]},"unlisted":false,"prevItem":{"title":"CVE-2026-49328 - Apache Fesod (Incubating): \u5bf9\u7528\u6237\u63d0\u4f9b\u7684URL\u9a8c\u8bc1\u4e0d\u5f53\u5bfc\u81f4SSRF\u6f0f\u6d1e","permalink":"/zh-cn/blog/2026/06/11/cve-2026-49328"},"nextItem":{"title":"\u4ece\u4f7f\u7528\u8005\u5230 Committer","permalink":"/zh-cn/blog/2026/04/29/from-user-to-committer"}},"content":"> \u672c\u6587\u4ecb\u7ecd\u5982\u4f55\u5229\u7528 OpenRewrite \u7f16\u5199\u58f0\u660e\u5f0f\u8fc1\u79fb\u914d\u7f6e\uff0c\u5c06\u9879\u76ee\u4ece `cn.idev.excel:fastexcel:1.3.0` \u8fc1\u79fb\u81f3 `org.apache.fesod:fesod-sheet:2.0.1-incubating`\uff0c\u9002\u7528\u4e8e Maven \u4e0e Gradle \u9879\u76ee\u3002\\n\\n\x3c!--truncate--\x3e\\n\\n## \u80cc\u666f\\n\\nFastExcel\uff08`cn.idev.excel`\uff09\u5df2\u6350\u8d60\u7ed9 Apache \u8f6f\u4ef6\u57fa\u91d1\u4f1a\uff0c\u5b75\u5316\u4e3a **Apache Fesod (Incubating)**\u3002\u8fc1\u79fb\u7684\u6838\u5fc3\u53d8\u5316\u662f **Java \u5305\u8def\u5f84\u66ff\u6362**\u2014\u2014API\u3001\u6ce8\u89e3\u548c\u5904\u7406\u903b\u8f91\u5b8c\u5168\u4e00\u81f4\uff0c\u5c5e\u4e8e\u4f4e\u98ce\u9669\u7684\u673a\u68b0\u91cd\u6784\u3002\\n\\n\u5b98\u65b9\u8fc1\u79fb\u7b56\u7565\u53c2\u8003\uff1a[https://fesod.apache.org/docs/migration/from-fastexcel/](https://fesod.apache.org/docs/migration/from-fastexcel/)\\n\\n\u624b\u52a8\u9010\u6587\u4ef6\u66ff\u6362 import \u65e2\u8017\u65f6\u53c8\u5bb9\u6613\u9057\u6f0f\u3002OpenRewrite \u63d0\u4f9b\u4e86 AST \u7ea7\u522b\u7684\u4ee3\u7801\u53d8\u6362\u80fd\u529b\uff0c\u80fd\u7cbe\u786e\u3001\u5b89\u5168\u5730\u5b8c\u6210\u8fd9\u7c7b\u6279\u91cf\u8fc1\u79fb\u3002\\n\\n## \u8fc1\u79fb\u8303\u56f4\\n\\n1. \u66f4\u65b0 Maven/Gradle \u4f9d\u8d56\\n2. \u5c06\u5df2\u5e9f\u5f03\u7684\u7c7b\u540d\u66ff\u6362\u4e3a `FesodSheet`\\n3. \u66f4\u65b0\u5305\u5bfc\u5165\\n\\n## \u7f16\u5199 OpenRewrite Recipe\\n\\n\u5728\u9879\u76ee\u6839\u76ee\u5f55\u521b\u5efa\u6587\u4ef6 `rewrite.yml`\uff1a\\n\\n```yaml\\n---\\ntype: specs.openrewrite.org/v1beta/recipe\\nname: org.apache.fesod.MigrateFastExcelToFesod\\ndisplayName: Migrate FastExcel 1.3 to Apache Fesod (Incubating) 2.0.1-incubating\\nrecipeList:\\n\\n  # \u6b65\u9aa4 1\uff1a\u66f4\u65b0\u4f9d\u8d56 (Maven & Gradle)\\n  - org.openrewrite.maven.ChangeDependencyGroupIdAndArtifactId:\\n      oldGroupId: cn.idev.excel\\n      oldArtifactId: fastexcel\\n      newGroupId: org.apache.fesod\\n      newArtifactId: fesod-sheet\\n      newVersion: 2.0.1-incubating\\n  - org.openrewrite.gradle.ChangeDependency:\\n      oldGroupId: cn.idev.excel\\n      oldArtifactId: fastexcel\\n      newGroupId: org.apache.fesod\\n      newArtifactId: fesod-sheet\\n      newVersion: 2.0.1-incubating\\n\\n  # \u6b65\u9aa4 2\uff1a\u66f4\u65b0\u5305\u5bfc\u5165\\n  - org.openrewrite.java.ChangePackage:\\n      oldPackageName: cn.idev.excel\\n      newPackageName: org.apache.fesod.sheet\\n      recursive: true\\n  - org.openrewrite.java.ChangePackage:\\n      oldPackageName: org.apache.fesod.excel\\n      newPackageName: org.apache.fesod.sheet\\n      recursive: true\\n\\n  # \u6b65\u9aa4 3\uff1a\u91cd\u547d\u540d\u5165\u53e3\u7c7b\\n  - org.openrewrite.java.ChangeType:\\n      oldFullyQualifiedTypeName: org.apache.fesod.sheet.FastExcel\\n      newFullyQualifiedTypeName: org.apache.fesod.sheet.FesodSheet\\n  - org.openrewrite.java.ChangeType:\\n      oldFullyQualifiedTypeName: org.apache.fesod.sheet.FastExcelFactory\\n      newFullyQualifiedTypeName: org.apache.fesod.sheet.FesodSheet\\n\\n  - org.openrewrite.text.FindAndReplace:\\n      find: ByFastExcelCGLIB\\n      replace: ByFesodCGLIB\\n      filePattern: \\"**/*.java\\"\\n```\\n\\n### \u6267\u884c\u903b\u8f91\u89e3\u6790\\n\\nRecipe \u6309\u58f0\u660e\u987a\u5e8f\u4f9d\u6b21\u6267\u884c\uff0c\u5206\u4e3a\u56db\u4e2a\u6b65\u9aa4\uff1a\\n\\n**Step 1 \u2014 \u66f4\u65b0\u4f9d\u8d56**\uff1aMaven \u9879\u76ee\u89e6\u53d1\u7b2c\u4e00\u6761\u89c4\u5219\u4fee\u6539 `pom.xml`\uff1bGradle \u9879\u76ee\u89e6\u53d1\u7b2c\u4e8c\u6761\u89c4\u5219\u4fee\u6539 `build.gradle` / `build.gradle.kts`\u3002\u5982\u679c\u9879\u76ee\u53ea\u4f7f\u7528\u5176\u4e2d\u4e00\u79cd\u6784\u5efa\u5de5\u5177\uff0c\u53e6\u4e00\u6761\u89c4\u5219\u81ea\u52a8\u8df3\u8fc7\uff0c\u4e0d\u4f1a\u62a5\u9519\u3002\\n\\n**Step 2 \u2014 \u66f4\u65b0\u5305\u5bfc\u5165**\uff1a`ChangePackage(recursive=true)` \u4e00\u6761\u89c4\u5219\u8986\u76d6 `cn.idev.excel` \u4e0b\u6240\u6709\u5b50\u5305\uff08annotation\u3001read\u3001write\u3001converters\u3001enums \u7b49\uff09\uff0c\u65e0\u9700\u9010\u4e2a\u679a\u4e3e\u3002\u7b2c\u4e8c\u6761\u89c4\u5219\u5904\u7406\u5df2\u90e8\u5206\u8fc1\u79fb\u5230 `org.apache.fesod.excel` \u7684\u9057\u7559\u4ee3\u7801\u3002\u8fd9\u4e00\u6b65\u4f1a\u5c06 `cn.idev.excel.FastExcel` \u7684 import \u6539\u4e3a `org.apache.fesod.sheet.FastExcel`\uff08Fesod \u4e2d\u7684 `@Deprecated` \u6865\u63a5\u7c7b\uff09\u3002\\n\\n**Step 3 \u2014 \u91cd\u547d\u540d\u5165\u53e3\u7c7b**\uff1aStep 2 \u5b8c\u6210\u540e\uff0c\u6240\u6709 `FastExcel` \u548c `FastExcelFactory` \u7684 import \u5df2\u7edf\u4e00\u6307\u5411 `org.apache.fesod.sheet` \u5305\u3002\u6b64\u65f6\u53ea\u9700\u4e24\u6761 `ChangeType` \u89c4\u5219\uff0c\u5c06\u5b83\u4eec\u6539\u4e3a\u6b63\u5f0f\u7684 `FesodSheet` \u7c7b\uff0c\u540c\u65f6\u81ea\u52a8\u5904\u7406\u6240\u6709\u8c03\u7528\u70b9\uff08`FastExcel.read()`\u3001`FastExcel.write()` \u7b49\uff09\u548c\u7c7b\u578b\u5f15\u7528\uff08\u53d8\u91cf\u58f0\u660e\u3001\u7c7b\u5b57\u9762\u91cf\uff09\u3002\\n\\n**Step 4 \u2014 CGLIB \u5b57\u7b26\u4e32\u66ff\u6362**\uff1a\u4ec5\u5bf9\u5f15\u7528\u4e86 CGLIB \u751f\u6210\u7c7b\u540d\u7684\u4ee3\u7801\u751f\u6548\uff0c\u591a\u6570\u9879\u76ee\u4e0d\u9700\u8981\u6b64\u6b65\u9aa4\uff0c\u4e0d\u5339\u914d\u5219\u81ea\u52a8\u8df3\u8fc7\u3002\\n\\n## \u5728\u9879\u76ee\u4e2d\u5f15\u5165 OpenRewrite\\n\\n### Maven \u9879\u76ee\\n\\n\u5728 `pom.xml` \u4e2d\u6dfb\u52a0\u63d2\u4ef6\uff1a\\n\\n```xml\\n<plugin>\\n    <groupId>org.openrewrite.maven</groupId>\\n    <artifactId>rewrite-maven-plugin</artifactId>\\n    <version>6.38.0</version>\\n    <configuration>\\n        <activeRecipes>\\n            <recipe>org.apache.fesod.MigrateFastExcelToFesod</recipe>\\n        </activeRecipes>\\n    </configuration>\\n</plugin>\\n```\\n\\n### Gradle (Groovy)\\n\\n\u5728 `build.gradle` \u4e2d\u5f15\u5165\uff1a\\n\\n```groovy\\nplugins {\\n    id \'java\'\\n    id \'maven-publish\'\\n    id \'org.openrewrite.rewrite\' version \'7.32.2\'\\n}\\n\\nrewrite {\\n    activeRecipe(\\n            \'org.apache.fesod.MigrateFastExcelToFesod\',\\n    )\\n}\\n```\\n\\n### Gradle (Kotlin)\\n\\n```kotlin\\nplugins {\\n    `java-library`\\n    `maven-publish`\\n    id(\\"org.openrewrite.rewrite\\") version \\"7.32.2\\"\\n}\\n\\nrewrite {\\n    activeRecipe(\\n        \\"org.apache.fesod.MigrateFastExcelToFesod\\",\\n    )\\n}\\n```\\n\\n## \u6267\u884c\u8fc1\u79fb\\n\\n### \u9884\u89c8\u53d8\u66f4\\n\\n\u5148\u67e5\u770b Recipe \u4f1a\u4ea7\u751f\u54ea\u4e9b\u4fee\u6539\uff0c\u4e0d\u5b9e\u9645\u6539\u52a8\u6587\u4ef6\uff1a\\n\\n```bash\\n# Maven\\n# \u9ed8\u8ba4\u8f93\u51fa\u8def\u5f84\uff1atarget/site/rewrite/rewrite.patch\\nmvn rewrite:dryRun\\n\\n# Gradle\\n# \u9ed8\u8ba4\u8f93\u51fa\u8def\u5f84\uff1abuild/reports/rewrite/rewrite.patch\\ngradle rewriteDryRun\\n```\\n\\n\u8f93\u51fa\u4f1a\u5217\u51fa\u6240\u6709\u5373\u5c06\u4fee\u6539\u7684\u6587\u4ef6\u548c\u5177\u4f53\u53d8\u66f4\u5185\u5bb9\u3002\\n\\n### \u6267\u884c\u8fc1\u79fb\\n\\n\u786e\u8ba4\u65e0\u8bef\u540e\uff0c\u6267\u884c\u5b9e\u9645\u4fee\u6539\uff1a\\n\\n```bash\\n# Maven\\nmvn rewrite:run\\n\\n# Gradle\\ngradle rewriteRun\\n```\\n\\n### \u9a8c\u8bc1\\n\\n```bash\\n# \u7f16\u8bd1\u68c0\u67e5\\nmvn compile\\n# \u6216\\ngradle compileJava\\n\\n# \u8fd0\u884c\u6d4b\u8bd5\\nmvn test\\n# \u6216\\ngradle test\\n```\\n\\n## \u8fc1\u79fb\u6548\u679c\u793a\u4f8b\\n\\n\u8fc1\u79fb\u524d\uff1a\\n\\n```java\\nimport cn.idev.excel.FastExcel;\\nimport cn.idev.excel.annotation.ExcelProperty;\\nimport cn.idev.excel.read.listener.ReadListener;\\n\\nFastExcel.write(outputStream, BookData.class)\\n        .sheet(\\"Sheet1\\")\\n        .doWrite(data());\\n```\\n\\n\u8fc1\u79fb\u540e\uff1a\\n\\n```java\\nimport org.apache.fesod.sheet.FesodSheet;\\nimport org.apache.fesod.sheet.annotation.ExcelProperty;\\nimport org.apache.fesod.sheet.read.listener.ReadListener;\\n\\nFesodSheet.write(outputStream, BookData.class)\\n        .sheet(\\"Sheet1\\")\\n        .doWrite(data());\\n```\\n\\n## \u53c2\u8003\\n\\n- Apache Fesod (Incubating) \u5b98\u65b9\u8fc1\u79fb\u6307\u5357\uff1a[https://fesod.apache.org/docs/migration/from-fastexcel/](https://fesod.apache.org/docs/migration/from-fastexcel/)\\n- OpenRewrite \u5b98\u65b9\u6587\u6863\uff1a[https://docs.openrewrite.org/](https://docs.openrewrite.org/)\\n- OpenRewrite Recipe \u53c2\u8003\uff1a[https://docs.openrewrite.org/recipes](https://docs.openrewrite.org/recipes)"},{"id":"/2026/04/29/from-user-to-committer","metadata":{"permalink":"/zh-cn/blog/2026/04/29/from-user-to-committer","editUrl":"https://github.com/apache/fesod/edit/main/website/i18n/zh-cn/docusaurus-plugin-content-blog/2026-04-29-from-user-to-committer.md","source":"@site/i18n/zh-cn/docusaurus-plugin-content-blog/2026-04-29-from-user-to-committer.md","title":"\u4ece\u4f7f\u7528\u8005\u5230 Committer","description":"\u4ece\u4f7f\u7528\u8005\u5230 Committer","date":"2026-04-29T00:00:00.000Z","tags":[{"inline":true,"label":"opensource","permalink":"/zh-cn/blog/tags/opensource"},{"inline":true,"label":"apache","permalink":"/zh-cn/blog/tags/apache"},{"inline":true,"label":"committer","permalink":"/zh-cn/blog/tags/committer"},{"inline":true,"label":"fesod","permalink":"/zh-cn/blog/tags/fesod"}],"hasTruncateMarker":true,"authors":[{"name":"Jing Yang","url":"https://github.com/bengbengbalabalabeng","socials":{"github":"https://github.com/bengbengbalabalabeng"},"imageURL":"data:image/png;base64,","key":"bengbengbalabalabeng","page":null}],"frontMatter":{"title":"\u4ece\u4f7f\u7528\u8005\u5230 Committer","description":"\u4ece\u4f7f\u7528\u8005\u5230 Committer","authors":["bengbengbalabalabeng"],"tags":["opensource","apache","committer","fesod"]},"unlisted":false,"prevItem":{"title":"\u4f7f\u7528 OpenRewrite \u4ece FastExcel 1.3.0 \u81ea\u52a8\u8fc1\u79fb\u5230 Apache Fesod (Incubating)","permalink":"/zh-cn/blog/2026/05/07/migration-from-fastexcel-with-openrewrite"},"nextItem":{"title":"Apache Fesod (Incubating) 2.0.1-incubating \u6b63\u5f0f\u53d1\u5e03","permalink":"/zh-cn/blog/2026/02/27/apache-fesod-2-0-1-incubating-released"}},"content":"![Apache Fesod New Committer](/img/blog/apache-fesod-new-committer.svg)\\n\\n\u5927\u5bb6\u597d\uff0c\u6211\u662f `bengbengbalabalabeng`\u3002\u975e\u5e38\u8363\u5e78\u80fd\u5728\u8fd9\u91cc\u4e0e\u5927\u5bb6\u5206\u4eab\u6211\u7684\u559c\u60a6\uff1a\u8fd1\u671f\u6211\u6b63\u5f0f\u53d7\u9080\u6210\u4e3a\u4e86 **Apache Fesod (Incubating)** \u9879\u76ee\u7684 Committer\u3002\\n\\n\u4ece\u6700\u521d\u7684\u666e\u901a\u7528\u6237\uff0c\u5230\u63d0\u4ea4\u7b2c\u4e00\u4e2a `Bugfix`\uff0c\u518d\u5230\u6df1\u5165\u53c2\u4e0e\u4ee3\u7801\u8d21\u732e\u3001\u6587\u6863\u5b8c\u5584\u4e0e\u793e\u533a\u7b54\u7591\uff0c\u8fd9\u4e00\u8def\u8d70\u6765\u6536\u83b7\u9887\u4e30\u3002\u501f\u6b64\u673a\u4f1a\uff0c\u6211\u60f3\u8bb0\u5f55\u4e00\u4e0b\u8fd9\u6bb5\u5f00\u6e90\u4e4b\u65c5\u3002\\n\\n\x3c!--truncate--\x3e\\n\\n## \u521d\u8bc6 Apache Fesod (Incubating)\\n\\n\u4f5c\u4e3a\u4e00\u540d Java \u5f00\u53d1\u8005\uff0c\u6211\u5728\u5de5\u4f5c\u4e2d\u7ecf\u5e38\u9762\u4e34\u5904\u7406\u590d\u6742 Excel \u6587\u4ef6\u7684\u9700\u6c42\u3002\u5728\u5bfb\u627e\u9ad8\u6548\u89e3\u51b3\u65b9\u6848\u7684\u8fc7\u7a0b\u4e2d\uff0c\u6211\u63a5\u89e6\u5230\u4e86 FastExcel\u3002\u5b83\u6781\u5927\u5730\u7b80\u5316\u4e86\u6211\u5728\u65e5\u5e38\u5f00\u53d1\u4e2d\u5904\u7406 Excel \u6570\u636e\u7684\u590d\u6742\u5ea6\u3002\\n\u540e\u6765\uff0c\u4e00\u4e2a\u4ee4\u4eba\u632f\u594b\u7684\u6d88\u606f\u4f20\u6765\uff1aFastExcel \u5ba3\u5e03\u5c06\u5176\u6350\u8d60\u7ed9 Apache \u8f6f\u4ef6\u57fa\u91d1\u4f1a\uff0c\u6b63\u5f0f\u8fdb\u5165\u5b75\u5316\u5668\u5e76\u66f4\u540d\u4e3a Apache Fesod (Incubating)\u3002\u90a3\u4e00\u523b\uff0c\u6211\u611f\u89c9\u8fd9\u4e2a\u9879\u76ee\u7684\u6d3b\u529b\u88ab\u63d0\u5347\u5230\u4e86\u4e00\u4e2a\u5168\u65b0\u7684\u9ad8\u5ea6\u3002\\n\u5b83\u65e2\u62e5\u6709 FastExcel \u65f6\u4ee3\u79ef\u7d2f\u7684\u5e9e\u5927\u7528\u6237\u57fa\u7840\u4e0e\u5f71\u54cd\u529b\uff0c\u53c8\u5c55\u73b0\u51fa\u4e86\u5728 Apache \u5f00\u6e90\u571f\u58e4\u4e2d\u672a\u88ab\u5b8c\u5168\u5f00\u53d1\u7684\u5de8\u5927\u6f5c\u529b\u3002\u8fd9\u79cd\u4f18\u79c0\u7684\u5de5\u5177\u5728\u66f4\u5927\u7684\u5e73\u53f0\u4e0a\u7115\u53d1\u201c\u65b0\u751f\u673a\u201d\u7684\u5947\u5999\u7ed3\u5408\u6df1\u6df1\u5438\u5f15\u4e86\u6211\u3002\\n\\n\u7136\u540e\uff0c\u6211\u4fbf\u5f00\u59cb\u5173\u6ce8\u793e\u533a\u7684\u52a8\u6001\uff0c\u4ece\u9ed8\u9ed8\u6f5c\u6c34\u5230\u5728 Issues \u91cc\u53c2\u4e0e\u5927\u5bb6\u7684\u8ba8\u8bba\uff0c\u518d\u5230\u63d0\u4ea4\u7b2c\u4e00\u4e2a PR([#668](https://github.com/apache/fesod/pull/668))\u3002\\n\\n## \u6211\u7684\u8d21\u732e\\n\\n\u6709\u4e86\u7b2c\u4e00\u6b21\u5408\u5e76 PR \u7684\u7ecf\u5386\u540e\uff0c\u6211\u4e0d\u518d\u5c40\u9650\u4e8e\u5355\u4e00\u7684\u62a5\u9519\u4fee\u590d\uff0c\u800c\u662f\u5c1d\u8bd5\u4ece\u6574\u4f53\u53bb\u5ba1\u89c6\u9879\u76ee\u3002\u4e3b\u8981\u662f\u8d21\u732e\u65b9\u5411\u5982\u4e0b\uff1a\\n\\n- **\u6587\u6863\u4f53\u7cfb\u5efa\u8bbe**\\n- **Bug \u4fee\u590d**\\n- **\u6d4b\u8bd5\u4f53\u7cfb\u5b8c\u5584**\\n- **\u529f\u80fd\u589e\u5f3a**\\n- **\u793e\u533a\u4e92\u52a8**\\n\\n## \u6211\u7684\u6536\u83b7\\n\\n\u5728\u53c2\u4e0e Apache Fesod (Incubating) \u7684\u8fc7\u7a0b\u4e2d\uff0c\u6211\u6df1\u523b\u4f53\u4f1a\u5230\uff1a\\n\\n- **\u5f00\u6e90\u4e0d\u53ea\u662f\u5199\u4ee3\u7801\u8fd8\u6709\u534f\u4f5c\u3002** Issue\u3001PR\u3001Review\u3001\u8ba8\u8bba\uff0c\u6bcf\u4e00\u6b65\u90fd\u9700\u8981\u6e05\u6670\u6c9f\u901a\u4e0e\u8010\u5fc3\u3002\\n- **\u5c0f\u8d21\u732e\u4e5f\u80fd\u4ea7\u751f\u5de8\u5927\u5f71\u54cd\u3002** \u4e00\u4e2a typo \u4fee\u590d\u3001\u4e00\u4e2a\u793a\u4f8b\u8865\u5145\uff0c\u90fd\u53ef\u80fd\u5e2e\u52a9\u6210\u5343\u4e0a\u4e07\u7684\u7528\u6237\u3002\\n- **\u793e\u533a\u7684\u529b\u91cf\u8fdc\u5927\u4e8e\u4e2a\u4eba\u3002** \u6bcf\u4e00\u6b21\u8ba8\u8bba\u3001\u6bcf\u4e00\u6b21\u5171\u8bc6\uff0c\u90fd\u8ba9\u9879\u76ee\u53d8\u5f97\u66f4\u597d\u3002\\n\\n## \u7ed3\u8bed\\n\\n\u6210\u4e3a Committer \u7edd\u4e0d\u662f\u7ec8\u70b9\uff0c\u800c\u662f\u4e00\u4e2a\u5168\u65b0\u7684\u8d77\u70b9\u3002\u5b83\u610f\u5473\u7740\u66f4\u591a\u7684\u8d23\u4efb\u548c\u66f4\u9ad8\u7684\u8981\u6c42\u3002\u6211\u5f88\u671f\u5f85\u4e0e\u793e\u533a\u4e00\u8d77\u628a Apache Fesod (Incubating) \u5efa\u8bbe\u5f97\u66f4\u597d\u3002"},{"id":"/2026/02/27/apache-fesod-2-0-1-incubating-released","metadata":{"permalink":"/zh-cn/blog/2026/02/27/apache-fesod-2-0-1-incubating-released","editUrl":"https://github.com/apache/fesod/edit/main/website/i18n/zh-cn/docusaurus-plugin-content-blog/2026-02-27-apache-fesod-2-0-1-incubating-released.md","source":"@site/i18n/zh-cn/docusaurus-plugin-content-blog/2026-02-27-apache-fesod-2-0-1-incubating-released.md","title":"Apache Fesod (Incubating) 2.0.1-incubating \u6b63\u5f0f\u53d1\u5e03","description":"Apache Fesod (Incubating) \u793e\u533a\u6b23\u7136\u5ba3\u5e03\uff0cApache Fesod (Incubating) 2.0.1-incubating \u7248\u672c\u6b63\u5f0f\u53d1\u5e03\uff01","date":"2026-02-27T00:00:00.000Z","tags":[{"inline":true,"label":"announcement","permalink":"/zh-cn/blog/tags/announcement"},{"inline":true,"label":"release","permalink":"/zh-cn/blog/tags/release"}],"hasTruncateMarker":true,"authors":[{"name":"Shuxin Pan","url":"https://github.com/psxjoy","socials":{"github":"https://github.com/psxjoy"},"imageURL":"data:image/png;base64,","key":"psxjoy","page":null}],"frontMatter":{"title":"Apache Fesod (Incubating) 2.0.1-incubating \u6b63\u5f0f\u53d1\u5e03","description":"Apache Fesod (Incubating) \u793e\u533a\u6b23\u7136\u5ba3\u5e03\uff0cApache Fesod (Incubating) 2.0.1-incubating \u7248\u672c\u6b63\u5f0f\u53d1\u5e03\uff01","authors":["psxjoy"],"tags":["announcement","release"],"date":"2026-02-27T00:00:00.000Z"},"unlisted":false,"prevItem":{"title":"\u4ece\u4f7f\u7528\u8005\u5230 Committer","permalink":"/zh-cn/blog/2026/04/29/from-user-to-committer"},"nextItem":{"title":"\u6b22\u8fce Apache Fesod \u65b0\u664b Committer","permalink":"/zh-cn/blog/2026/02/27/welcome-new-committer"}},"content":"**2026\u5e742\u6708** \u2014\u2014 Apache Fesod (Incubating) \u793e\u533a\u6b23\u7136\u5ba3\u5e03\uff0c**Apache Fesod (Incubating) 2.0.1-incubating \u7248\u672c\u6b63\u5f0f\u53d1\u5e03\uff01**\\n\\n\u8fd9\u4e0d\u4ec5\u662f\u4e00\u4e2a\u6280\u672f\u7248\u672c\u7684\u8fed\u4ee3\uff0c\u66f4\u662f Fesod \u9879\u76ee\u81ea\u52a0\u5165 **Apache \u8f6f\u4ef6\u57fa\u91d1\u4f1a (ASF)** \u5b75\u5316\u5668\u4ee5\u6765\u7684**\u9996\u4e2a\u6b63\u5f0f\u53d1\u5e03\u7248\u672c**\u3002\u5728\u8fc7\u53bb\u7684\u51e0\u4e2a\u6708\u4e2d\uff0c\u793e\u533a\u6210\u5458\u5171\u540c\u5b8c\u6210\u4e86\u5927\u91cf\u7684\u5408\u89c4\u6027\u6539\u9020\u3001\u67b6\u6784\u91cd\u6784\u4ee5\u53ca\u529f\u80fd\u589e\u5f3a\uff0c\u6807\u5fd7\u7740 Fesod \u5df2\u7ecf\u5b8c\u5168\u51c6\u5907\u597d\u5728 ASF \u89c4\u8303\u4e0b\u5f00\u542f\u9ad8\u6027\u80fd Excel \u5904\u7406\u7684\u65b0\u7bc7\u7ae0\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n## \u91cc\u7a0b\u7891\u610f\u4e49\uff1a\u9996\u4e2a\u6b63\u5f0f\u7684 ASF Release\\n\\n\u4f5c\u4e3a\u8fdb\u5165\u5b75\u5316\u5668\u540e\u7684\u201c\u5904\u5b50\u79c0\u201d\uff0c2.0.1 \u7248\u672c\u5728 **Apache Way\uff08Apache \u4e4b\u9053\uff09** \u65b9\u9762\u53d6\u5f97\u4e86\u51b3\u5b9a\u6027\u8fdb\u5c55\uff1a\\n\\n* **\u5168\u9762\u66f4\u540d\u4e0e\u5408\u89c4\uff1a** \u6211\u4eec\u5b8c\u6210\u4e86\u4ece `FastExcel` \u5230 `Fesod` \u7684\u5168\u9762\u91cd\u547d\u540d\uff08\u5305\u62ec\u5305\u540d\u3001\u7c7b\u540d\u53ca\u6587\u6863\uff09\uff0c\u786e\u4fdd\u54c1\u724c\u5b8c\u5168\u53d7 ASF \u4fdd\u62a4\u3002\\n* **\u5408\u89c4\u6027\u8865\u5168\uff1a** \u5f15\u5165\u4e86 `DISCLAIMER`\u3001`NOTICE` \u4ee5\u53ca `support` \u6a21\u5757\uff0c\u5e76\u901a\u8fc7 Spotless \u5b9e\u73b0\u4e86\u81ea\u52a8\u5316\u7684 License Header \u7ba1\u7406\uff0c\u5b8c\u5168\u7b26\u5408 ASF \u7684\u653f\u7b56\u8981\u6c42\u3002\\n* **\u793e\u533a\u6cbb\u7406\uff1a** \u6240\u6709\u7684\u4ee3\u7801\u5408\u5e76\u4e0e\u7248\u672c\u53d1\u5e03\u5747\u7ecf\u8fc7\u4e86\u793e\u533a\u6295\u7968\u4e0e\u90ae\u4ef6\u5217\u8868\u8ba8\u8bba\uff0c\u4f53\u73b0\u4e86\u516c\u5f00\u3001\u900f\u660e\u7684\u6cbb\u7406\u539f\u5219\u3002\\n\\n## \u7248\u672c\u6838\u5fc3\u4eae\u70b9\\n\\n### 1. \u67b6\u6784\u6df1\u5ea6\u91cd\u6784\\n\\n\u4e3a\u4e86\u652f\u6301\u66f4\u957f\u8fdc\u7684\u53d1\u5c55\uff0c\u6211\u4eec\u5bf9\u9879\u76ee\u7ed3\u6784\u8fdb\u884c\u4e86\u5927\u89c4\u6a21\u4f18\u5316\uff1a\\n\\n* **\u591a\u6a21\u5757\u5316\uff08Multi-module\uff09\uff1a** \u5f15\u5165\u4e86\u591a\u6a21\u5757\u67b6\u6784\uff0c\u4f7f\u9879\u76ee\u5c42\u6b21\u66f4\u6e05\u6670\uff0c\u4f9d\u8d56\u7ba1\u7406\u66f4\u7cbe\u7ec6\u3002\\n* **\u5206\u53d1\u589e\u5f3a\uff1a** \u65b0\u589e `fesod-distribution` \u6a21\u5757\uff0c\u89c4\u8303\u4e86\u5206\u53d1\u5305\u7684\u63cf\u8ff0\u4e0e\u6784\u5efa\u3002\\n* **JDK 25 \u652f\u6301\uff1a** \u7d27\u8ddf Java \u751f\u6001\uff0c\u6b63\u5f0f\u589e\u52a0\u4e86\u5bf9 **JDK 25** \u7684\u517c\u5bb9\u4e0e\u652f\u6301\u3002\\n\\n### 2. \u529f\u80fd\u7279\u6027 (Features)\\n\\n\u672c\u6b21\u53d1\u5e03\u5f15\u5165\u4e86\u591a\u9879\u5b9e\u7528\u65b0\u529f\u80fd\uff0c\u8fdb\u4e00\u6b65\u589e\u5f3a\u4e86 Excel \u5904\u7406\u7684\u7075\u6d3b\u6027\uff1a\\n\\n* **Excel \u5904\u7406\u589e\u5f3a\uff1a** \u5728 `SheetWriteHandler` \u4e2d\u65b0\u589e\u4e86 `afterSheetDispose` \u751f\u547d\u5468\u671f\u65b9\u6cd5\uff0c\u5e76\u5f15\u5165\u4e86\u5168\u65b0\u7684**\u8868\u5934\u5408\u5e76\u7b56\u7565\uff08Header Merge Strategy\uff09**\u3002\\n* **\u8001\u7248\u672c\u517c\u5bb9\uff1a** \u4f18\u96c5\u5730\u5904\u7406\u4e86\u6781\u8001\u7248\u672c\u7684 Excel BIFF \u683c\u5f0f\uff0c\u907f\u514d\u8fd0\u884c\u5d29\u6e83\u3002\\n* **\u7075\u6d3b\u63a7\u5236\uff1a** \u65b0\u589e `autoStrip` \u53c2\u6570\uff0c\u5e76\u5728 `Workbook` \u5e38\u91cf\u4e2d\u5f15\u5165\u4e86\u6700\u5927 Sheet \u540d\u79f0\u957f\u5ea6\u6821\u9a8c\u3002\\n* **\u7f51\u7ad9\u4f53\u9a8c\uff1a** \u5b98\u65b9\u6587\u6863\u65b0\u589e\u4e86\u672c\u5730\u641c\u7d22\u529f\u80fd\u53ca Matomo \u7edf\u8ba1\u63d2\u4ef6\uff0c\u5e76\u4f18\u5316\u4e86\u79fb\u52a8\u7aef\u5c55\u793a\u3002\\n\\n### 3. \u7a33\u5b9a\u6027\u4e0e\u5065\u58ee\u6027 (Stability)\\n\\n\u6211\u4eec\u6295\u5165\u4e86\u5927\u91cf\u7cbe\u529b\u5728\u8d28\u91cf\u4fdd\u969c\u4e0a\uff1a\\n\\n* **\u6a21\u7cca\u6d4b\u8bd5 (Fuzz Testing)\uff1a** \u4e3a Excel \u8bfb\u53d6\u589e\u52a0\u4e86\u6bcf\u65e5\u6a21\u7cca\u6d4b\u8bd5\u4efb\u52a1\uff0c\u80fd\u66f4\u65e9\u53d1\u73b0\u5904\u7406\u5f02\u5e38\u6587\u4ef6\u65f6\u7684\u6f5c\u5728\u5d29\u6e83\u3002\\n* **\u4f9d\u8d56\u5b89\u5168\uff1a** \u5347\u7ea7\u4e86 Spring-core\u3001Logback\u3001Fastjson2 \u4ee5\u53ca POI\uff08\u5347\u7ea7\u81f3 5.5.1\uff09\u7b49\u6838\u5fc3\u4f9d\u8d56\uff0c\u4fee\u590d\u4e86\u591a\u9879\u5df2\u77e5\u6f0f\u6d1e\u3002\\n* **CI/CD \u4f18\u5316\uff1a** \u5f15\u5165\u4e86 Netlify \u9884\u89c8\u90e8\u7f72\u548c\u81ea\u52a8\u5173\u95ed\u8fc7\u671f Issue \u7684\u5de5\u4f5c\u6d41\uff0c\u663e\u8457\u63d0\u5347\u4e86\u793e\u533a\u534f\u4f5c\u6548\u7387\u3002\\n\\n## \u5173\u952e\u53d8\u66f4\u6982\u89c8\\n\\n### **\u65b0\u529f\u80fd (Feature)**\\n\\n* `SheetWriteHandler` \u589e\u52a0 `afterSheetDispose` \u65b9\u6cd5\u3002\\n* \u589e\u52a0 Excel \u5199\u5165\u7684\u8868\u5934\u5408\u5e76\u7b56\u7565\u3002\\n* \u589e\u52a0 GitHub Actions \u7684 Netlify \u9884\u89c8\u90e8\u7f72\u652f\u6301\u3002\\n* \u589e\u52a0 `docusaurus-search-local` \u63d2\u4ef6\u4ee5\u652f\u6301\u5b98\u7f51\u641c\u7d22\u3002\\n\\n### **\u4fee\u590d (Bugfix)**\\n\\n* \u4fee\u590d `WriteSheetWorkbookWriteHandler` \u7c7b\u4e2d\u7684 NPE \u5f02\u5e38\u3002\\n* \u4fee\u590d\u6587\u6863\u4e2d\u9519\u8bef\u7684\u793a\u4f8b\u4ee3\u7801\u53ca\u8fc7\u671f\u7684\u94fe\u63a5\u3002\\n* \u5347\u7ea7\u4f9d\u8d56\u4ee5\u4fee\u590d\u6f0f\u6d1e\u544a\u8b66\uff0c\u5e76\u66f4\u65b0 import \u8bed\u53e5\u4ee5\u4f7f\u7528 shaded \u540e\u7684 cglib \u62a5\u540d\u3002\\n\\n### **\u91cd\u6784 (Refactor)**\\n\\n* \u5c06\u9879\u76ee\u91cd\u547d\u540d\u4e3a Fesod/FesodSheet\uff0c\u5e76\u66f4\u65b0\u5305\u7ed3\u6784\u4ee5\u7b26\u5408 Apache \u547d\u540d\u89c4\u8303\u3002\\n* \u5f15\u5165 Spotless \u81ea\u52a8\u7ba1\u7406 License Header\u3002\\n* \u79fb\u9664\u8fc7\u671f\u4e14\u4e0d\u6b63\u786e\u7684 `@since` \u6807\u7b7e\uff0c\u7cbe\u7b80\u6838\u5fc3\u7c7b\u3002\\n\\n> \u8be6\u7ec6\u7684\u53d8\u66f4\u5217\u8868\u8bf7\u53c2\u8003\uff1a[GitHub Release Notes](https://github.com/apache/fesod/releases/tag/2.0.1-incubating)\\n\\n## \u81f4\u8c22\\n\\n\u201c\u793e\u533a\u4f18\u4e8e\u4ee3\u7801\u201d\u662f Apache \u7684\u6838\u5fc3\u7406\u5ff5\u3002\u611f\u8c22\u6240\u6709\u4e3a\u6b64\u7248\u672c\u505a\u51fa\u8d21\u732e\u7684\u5f00\u53d1\u8005\u3001Mentors \u4ee5\u53ca\u793e\u533a\u6210\u5458\u3002\\n\\n### \u65b0\u8d21\u732e\u8005 (New Contributors)\\n\\n\u6211\u4eec\u8981\u7279\u522b\u6b22\u8fce\u5e76\u611f\u8c22\u5728\u8be5\u7248\u672c\u4e2d\u505a\u51fa\u9996\u6b21\u8d21\u732e\u7684 **14 \u4f4d\u65b0\u6210\u5458**\uff1a\\n\\n> @X-qinghai, @ngocnhan-tran1996, @YIminta, @jounghu, @wlgusqkr, @gaushon, @GOODBOY008, @ongdisheng, @harshasiddartha, @pjfanning, @liugddx, @hezhangjian, @bengbengbalabalabeng\\n\\n\u7279\u522b\u611f\u8c22 **@delei, @psxjoy, @alaahong, @ongdisheng, @GOODBOY008** \u4ee5\u53ca\u6240\u6709\u5728 GitHub \u4e0a\u63d0\u4ea4 PR \u548c\u5efa\u8bae\u7684\u670b\u53cb\u4eec\u3002\u6b63\u662f\u7531\u4e8e\u4f60\u4eec\u5728\u91cd\u547d\u540d\u3001\u5408\u89c4\u6027\u68c0\u67e5\u3001CI \u4f18\u5316\u4ee5\u53ca\u6838\u5fc3\u529f\u80fd\u6539\u8fdb\u4e0a\u7684\u4e0d\u61c8\u52aa\u529b\uff0c\u624d\u4fc3\u6210\u4e86 Fesod \u5728 Apache \u7684\u5b8c\u7f8e\u9996\u79c0\u3002\\n\\n## \u5982\u4f55\u83b7\u53d6\\n\\n\u4f60\u53ef\u4ee5\u901a\u8fc7\u4ee5\u4e0b\u6e20\u9053\u4e0b\u8f7d\u5e76\u4f53\u9a8c\u5168\u65b0\u7684 Apache Fesod (Incubating) \uff1a\\n\\n* **\u5b98\u65b9\u7f51\u7ad9\uff1a** [https://fesod.apache.org/](https://fesod.apache.org/)\\n* **\u6e90\u7801\u4ed3\u5e93\uff1a** [https://github.com/apache/fesod](https://github.com/apache/fesod)\\n* **Maven \u5750\u6807\uff1a**\\n\\n```xml\\n<dependency>\\n    <groupId>org.apache.fesod</groupId>\\n    <artifactId>fesod</artifactId>\\n    <version>2.0.1-incubating</version>\\n</dependency>\\n```\\n\\n**\u6b22\u8fce\u52a0\u5165\u6211\u4eec\uff01**\\nApache Fesod (Incubating) \u793e\u533a\u59cb\u7ec8\u5bf9\u5f00\u53d1\u8005\u4fdd\u6301\u5f00\u653e\u3002\u4f60\u53ef\u4ee5\u901a\u8fc7\u8ba2\u9605\u90ae\u4ef6\u5217\u8868 `dev@fesod.apache.org` \u6216\u5728 GitHub \u4e0a\u63d0\u4ea4 Issue \u4e0e\u6211\u4eec\u4ea4\u6d41\u3002\\n\\n\u8ba9\u6211\u4eec\u5171\u540c\u671f\u5f85 Fesod \u5728 Apache \u5b75\u5316\u5668\u4e2d\u8301\u58ee\u6210\u957f\uff01"},{"id":"/2026/02/27/welcome-new-committer","metadata":{"permalink":"/zh-cn/blog/2026/02/27/welcome-new-committer","editUrl":"https://github.com/apache/fesod/edit/main/website/i18n/zh-cn/docusaurus-plugin-content-blog/2026-02-27-welcome-new-committer.md","source":"@site/i18n/zh-cn/docusaurus-plugin-content-blog/2026-02-27-welcome-new-committer.md","title":"\u6b22\u8fce Apache Fesod \u65b0\u664b Committer","description":"\u6b22\u8fce Apache Fesod \u65b0\u664b Committer","date":"2026-02-27T00:00:00.000Z","tags":[{"inline":true,"label":"opensource","permalink":"/zh-cn/blog/tags/opensource"},{"inline":true,"label":"apache","permalink":"/zh-cn/blog/tags/apache"},{"inline":true,"label":"committer","permalink":"/zh-cn/blog/tags/committer"},{"inline":true,"label":"fesod","permalink":"/zh-cn/blog/tags/fesod"}],"hasTruncateMarker":true,"authors":[{"name":"Zhongqiang Gong","url":"https://github.com/GOODBOY008","socials":{"github":"https://github.com/GOODBOY008"},"imageURL":"data:image/png;base64,","key":"GOODBOY008","page":null}],"frontMatter":{"title":"\u6b22\u8fce Apache Fesod \u65b0\u664b Committer","description":"\u6b22\u8fce Apache Fesod \u65b0\u664b Committer","authors":["GOODBOY008"],"tags":["opensource","apache","committer","fesod"]},"unlisted":false,"prevItem":{"title":"Apache Fesod (Incubating) 2.0.1-incubating \u6b63\u5f0f\u53d1\u5e03","permalink":"/zh-cn/blog/2026/02/27/apache-fesod-2-0-1-incubating-released"},"nextItem":{"title":"\u5b98\u5ba3! Fesod \u6210\u529f\u8fdb\u5165 Apache \u5b75\u5316\u5668","permalink":"/zh-cn/blog/2025/09/17/fesod-entered-apache-incubator"}},"content":"![Apache Fesod New Committer](/img/blog/apache-fesod-new-committer.svg)\\n\\n> \u5927\u5bb6\u597d\uff01\u975e\u5e38\u8363\u5e78\u53d7\u5230 Apache Fesod \u793e\u533a\u7684\u9080\u8bf7\uff0c\u6210\u4e3a\u4e00\u540d Committer\u3002\u5728\u6b64\uff0c\u6211\u60f3\u4e0e\u5927\u5bb6\u5206\u4eab\u6211\u7684\u5f00\u6e90\u4e4b\u65c5\u4ee5\u53ca\u4e00\u8def\u8d70\u6765\u7684\u7ecf\u5386\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n## \u81ea\u6211\u4ecb\u7ecd\\n\\n\u6211\u53eb\u9f9a\u4e2d\u5f3a\uff08GitHub: [GOODBOY008](https://github.com/GOODBOY008)\uff09\uff0c\u662f\u4e00\u540d\u70ed\u7231\u5f00\u6e90\u548c Java \u751f\u6001\u7684\u8f6f\u4ef6\u5de5\u7a0b\u5e08\uff0c\u540c\u65f6\u4e5f\u662f **Apache Flink Committer** \u548c **Apache StreamPark Committer**\u3002\\n\\n## \u4e0e Apache Fesod \u7684\u521d\u9047\\n\\n\u6211\u7b2c\u4e00\u6b21\u63a5\u89e6 Fesod \u662f\u5728 **2025 \u5e74 9 \u6708**\uff0c\u5f7c\u65f6\u9879\u76ee\u521a\u521a\u8fdb\u5165 Apache \u5b75\u5316\u9636\u6bb5\u3002\u4f5c\u4e3a\u4e00\u4e2a\u88ab\u5e7f\u6cdb\u4f7f\u7528\u7684 Java \u7535\u5b50\u8868\u683c\u5904\u7406\u5e93\uff0c\u5b83\u5df2\u7ecf\u62e5\u6709\u4e86\u575a\u5b9e\u7684\u7528\u6237\u57fa\u7840\u2014\u2014\u800c\u5728 Apache \u6cbb\u7406\u4e0b\uff0c\u9879\u76ee\u66f4\u662f\u5145\u6ee1\u4e86\u6210\u957f\u7a7a\u95f4\u3002\u8fd9\u79cd\u73b0\u5b9e\u5f71\u54cd\u529b\u4e0e\u672a\u88ab\u5f00\u53d1\u7684\u6f5c\u529b\u7684\u7ed3\u5408\u6df1\u6df1\u5438\u5f15\u4e86\u6211\uff0c\u8ba9\u6211\u660e\u786e\u4e86\u8981\u53c2\u4e0e\u5851\u9020\u5176\u5f00\u6e90\u672a\u6765\u7684\u51b3\u5fc3\u3002\\n\\n## \u6211\u7684\u8d21\u732e\\n\\n\u52a0\u5165\u793e\u533a\u4ee5\u6765\uff0c\u6211\u7684\u8d21\u732e\u6db5\u76d6\u4e86\u516d\u4e2a\u5173\u952e\u9886\u57df\uff1a\\n\\n- **\u54c1\u724c\u8fc1\u79fb** \u2014 \u63a8\u52a8\u4e86\u4ece FastExcel \u5230 FesodSheet \u7684\u7cfb\u7edf\u6027\u8fc1\u79fb\uff0c\u8986\u76d6\u6838\u5fc3\u7c7b\u3001\u6d4b\u8bd5\u4ee3\u7801\u3001\u793a\u4f8b\u7a0b\u5e8f\u53ca\u9762\u5411\u7528\u6237\u7684\u9519\u8bef\u63d0\u793a\u4fe1\u606f\u3002\\n- **\u4ee3\u7801\u8d28\u91cf** \u2014 \u6d88\u9664\u4e86\u91cd\u590d\u7684\u5de5\u5177\u7c7b\uff0c\u89c4\u8303\u4e86 Lombok \u7684\u4f7f\u7528\uff0c\u4f18\u5316\u4e86\u6d4b\u8bd5\u65ad\u8a00\u6a21\u5f0f\uff0c\u63d0\u5347\u4e86\u53ef\u7ef4\u62a4\u6027\u3002\\n- **CI/CD** \u2014 \u4e3a GitHub Actions \u5f15\u5165\u4e86\u5e76\u53d1\u63a7\u5236\u3001\u57fa\u4e8e\u8def\u5f84\u7684\u8fc7\u6ee4\u548c Fork \u4fdd\u62a4\u673a\u5236\uff0c\u4f7f\u6d41\u6c34\u7ebf\u66f4\u5feb\u3001\u66f4\u7ecf\u6d4e\u3002\\n- **\u6587\u6863** \u2014 \u7f16\u5199\u4e86\u4e2d\u82f1\u53cc\u8bed\u8fc1\u79fb\u6307\u5357\uff0c\u5e76\u4f18\u5316\u4e86\u6587\u6863\u7ad9\u70b9\u7684\u5bfc\u822a\u7ed3\u6784\u3002\\n- **\u6d4b\u8bd5\u4e0e\u6027\u80fd** \u2014 \u5efa\u7acb\u4e86\u5171\u4eab testkit \u57fa\u7840\u8bbe\u65bd\uff0c\u663e\u8457\u51cf\u5c11\u4e86\u6d4b\u8bd5\u91cd\u590d\u4ee3\u7801\uff0c\u5e76\u5f15\u5165\u4e86\u57fa\u4e8e JMH \u7684\u57fa\u51c6\u6d4b\u8bd5\u6846\u67b6\u8fdb\u884c\u6027\u80fd\u9a8c\u8bc1\u3002\\n- **\u67b6\u6784** \u2014 \u63d0\u51fa\u5e76\u63a8\u52a8\u4e86\u793a\u4f8b\u6a21\u5757\u91cd\u6784\u3001\u73b0\u4ee3\u5316\u6d4b\u8bd5\u6a21\u5f0f\u4ee5\u53ca\u957f\u671f\u6027\u80fd\u6d4b\u8bd5\u6846\u67b6\u7684\u8ba8\u8bba\u3002\\n\\n## \u6211\u7684\u6536\u83b7\\n\\n\u53c2\u4e0e Apache \u9879\u76ee\u8ba9\u6211\u5b66\u5230\u4e86\u4e09\u4ef6\u4e8b\uff1a**\u793e\u533a\u91cd\u4e8e\u4ee3\u7801** \u2014 \u5171\u8bc6\u548c\u900f\u660e\u5ea6\u6bd4\u4efb\u4f55\u5355\u4e2a PR \u90fd\u91cd\u8981\uff1b**\u4ece\u5c0f\u5904\u7740\u624b\uff0c\u653e\u773c\u5168\u5c40** \u2014 \u6211\u7684\u7b2c\u4e00\u4e2a\u5c0f\u578b CI \u4fee\u590d\uff08[#664](https://github.com/apache/fesod/pull/664)\uff09\u6700\u7ec8\u5f15\u53d1\u4e86\u6df1\u5c42\u6b21\u7684\u57fa\u7840\u8bbe\u65bd\u6539\u8fdb\uff1b**\u8d28\u91cf\u7684\u590d\u5229\u6548\u5e94** \u2014 \u6bcf\u4e00\u6b21\u5c0f\u7684\u4ee3\u7801\u6e05\u7406\uff0c\u65e5\u79ef\u6708\u7d2f\u90fd\u4f1a\u8ba9\u4ee3\u7801\u5e93\u66f4\u52a0\u5065\u5eb7\u3002\\n\\n## \u7ed9\u65b0\u8d21\u732e\u8005\u7684\u5efa\u8bae\\n\\n1. **\u8fc8\u51fa\u7b2c\u4e00\u6b65\u3002** \u627e\u4e00\u4e2a \\"good first issue\\" \u5f00\u59cb\u2014\u2014\u8fd9\u5f80\u5f80\u662f\u6700\u96be\u7684\u4e00\u6b65\u3002\\n2. **\u5148\u8bfb\u540e\u5199\u3002** \u5148\u7406\u89e3\u9879\u76ee\u7684\u67b6\u6784\u548c\u89c4\u8303\uff0c\u518d\u52a8\u624b\u7f16\u7801\u3002\\n3. **\u5f00\u653e\u6c9f\u901a\u3002** \u6e05\u6670\u7684 Issue \u548c PR \u6bd4\u4ee3\u7801\u672c\u8eab\u66f4\u80fd\u8d62\u5f97\u4fe1\u4efb\u3002\\n4. **\u7740\u773c\u957f\u8fdc\u3002** \u63d0\u6848\u3001\u6587\u6863\u548c\u57fa\u7840\u8bbe\u65bd\u7684\u6539\u8fdb\u540c\u6837\u662f\u91cd\u8981\u7684\u8d21\u732e\u3002\\n5. **\u4fdd\u6301\u8010\u5fc3\u3002** \u6301\u4e4b\u4ee5\u6052\u6bd4\u5feb\u901f\u51b2\u523a\u66f4\u91cd\u8981\u3002\\n\\n## \u5c55\u671b\u672a\u6765\\n\\n\u6210\u4e3a Committer \u662f\u4e00\u4e2a\u65b0\u7684\u8d77\u70b9\u3002\u6211\u5c06\u81f4\u529b\u4e8e\u63d0\u5347 Fesod \u7684\u4ee3\u7801\u8d28\u91cf\u3001\u6307\u5bfc\u65b0\u8d21\u732e\u8005\u3001\u63a8\u8fdb\u57fa\u51c6\u6d4b\u8bd5\u6846\u67b6\u7684\u5efa\u8bbe\uff0c\u5e76\u52a9\u529b Fesod \u4ece Apache \u5b75\u5316\u5668\u6bd5\u4e1a\u3002"},{"id":"/2025/09/17/fesod-entered-apache-incubator","metadata":{"permalink":"/zh-cn/blog/2025/09/17/fesod-entered-apache-incubator","editUrl":"https://github.com/apache/fesod/edit/main/website/i18n/zh-cn/docusaurus-plugin-content-blog/2025-09-17-fesod-entered-apache-incubator.md","source":"@site/i18n/zh-cn/docusaurus-plugin-content-blog/2025-09-17-fesod-entered-apache-incubator.md","title":"\u5b98\u5ba3! Fesod \u6210\u529f\u8fdb\u5165 Apache \u5b75\u5316\u5668","description":"Fesod successfully entered Apache Incubator.","date":"2025-09-17T00:00:00.000Z","tags":[{"inline":true,"label":"announcement","permalink":"/zh-cn/blog/tags/announcement"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"\u5b98\u5ba3! Fesod \u6210\u529f\u8fdb\u5165 Apache \u5b75\u5316\u5668","description":"Fesod successfully entered Apache Incubator.","tags":["announcement"]},"unlisted":false,"prevItem":{"title":"\u6b22\u8fce Apache Fesod \u65b0\u664b Committer","permalink":"/zh-cn/blog/2026/02/27/welcome-new-committer"}},"content":"\u5317\u4eac\u65f6\u95f42025\u5e7409\u670817\u65e5\uff0c[Fesod](https://github.com/apache/fesod)\\n\u6b63\u5f0f\u987a\u5229\u901a\u8fc7 Apache \u57fa\u91d1\u4f1a\u5b75\u5316\u5668\u7684\u6295\u7968\u51b3\u8bae\uff0c\u6839\u636e Apache\\n\u57fa\u91d1\u4f1a[\u90ae\u4ef6\u5217\u8868](https://lists.apache.org/thread/k744v8ff22mom3bplqkjnc2qvtksj59f)\u663e\u793a\uff0c\u6700\u7ec8\u4ee5 9\\n\u4e2a\u7ea6\u675f\u6027\u6295\u7968 (binding votes) \uff0c\u65e0\u5f03\u6743\u548c\u53cd\u5bf9\u7968\u901a\u8fc7\u63a5\u53d7 Fesod \u52a0\u5165 Apache\\n\u5b75\u5316\u5668\u51b3\u8bae\u3002\u6b63\u5f0f\u6210\u4e3a\u4e86\u5168\u7403\u6700\u5927\u7684\u5f00\u6e90\u57fa\u91d1\u4f1a [Apache \u8f6f\u4ef6\u57fa\u91d1\u4f1a](https://www.apache.org/) \u7684\u5b75\u5316\u9879\u76ee\u30022025\u5e7409\u670825\u65e5\uff0cFesod\\n\u4ed3\u5e93\u6b63\u5f0f\u8fc1\u79fb\u81f3 Apache \u8f6f\u4ef6\u57fa\u91d1\u4f1a\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\nFesod \u539f\u540d [FastExcel](https://github.com/fast-excel), \u4e8e 2024 \u5e74 10 \u6708\u5728 GitHub\\n\u6b63\u5f0f\u5f00\u6e90\uff0c\u7ecf\u8fc7\u793e\u533a\u5c0f\u4f19\u4f34\u4eec\u7684\u4e0d\u95f4\u65ad\u9879\u76ee\u7ef4\u62a4\u8fed\u4ee3\uff0c\u6301\u7eed\u7684\u793e\u533a\u6210\u957f\uff0c\u73b0\u5728\uff0cFesod\\n\u9879\u76ee\u6b63\u5f0f\u5b98\u5ba3\u52a0\u5165 Apache \u5b75\u5316\u5668\uff0c\u8fd9\u662f Fesod \u9879\u76ee\u7684\u65b0\u8d77\u70b9\uff0c\u610f\u5473\u7740\u5f00\u6e90\u793e\u533a\u5316\u534f\u4f5c\u5c06\u4f1a\u53d8\u5f97\u66f4\u52a0\u89c4\u8303\u4ee5\u53ca\u56fd\u9645\u5316\uff01\\n\\n![blog-20250917](/img/blog/20250917-01.png)\\n\\n## \u7b80\u4ecb\\n\\nApache Fesod (Incubating) \u662f\u4e00\u4e2a\u9ad8\u6027\u80fd\u3001\u5185\u5b58\u9ad8\u6548\u7684 Java \u5e93\uff0c\u7528\u4e8e\u8bfb\u5199\u7535\u5b50\u8868\u683c\u6587\u4ef6\uff0c\u65e8\u5728\u7b80\u5316\u5f00\u53d1\u5e76\u786e\u4fdd\u53ef\u9760\u6027\u3002\u540d\u79f0 fesod\uff08\u53d1\u97f3\u4e3a\\n`/\u02c8f\u025bs\u0252d/`\uff09\uff0c\u662f \\"fast easy spreadsheet and other documents\\"\uff08\u5feb\u901f\u7b80\u5355\u7684\u7535\u5b50\u8868\u683c\u548c\u5176\u4ed6\u6587\u6863\uff09\u7684\u9996\u5b57\u6bcd\u7f29\u5199\uff0c\u8868\u8fbe\u4e86\u9879\u76ee\u7684\u8d77\u6e90\u3001\u80cc\u666f\u548c\u613f\u666f\u3002\\n\\nApache Fesod (Incubating) \u53ef\u4ee5\u4e3a\u5f00\u53d1\u8005\u548c\u4f01\u4e1a\u63d0\u4f9b\u6781\u5927\u7684\u81ea\u7531\u5ea6\u548c\u7075\u6d3b\u6027\u3002\u6211\u4eec\u8ba1\u5212\u5728\u672a\u6765\u5f15\u5165\u66f4\u591a\u65b0\u529f\u80fd\uff0c\u4ee5\u6301\u7eed\u63d0\u5347\u7528\u6237\u4f53\u9a8c\u548c\u5de5\u5177\u53ef\u7528\u6027\u3002Apache\\nFesod (Incubating) \u81f4\u529b\u4e8e\u6210\u4e3a\u60a8\u5904\u7406\u7535\u5b50\u8868\u683c\u6587\u4ef6\u7684\u6700\u4f73\u9009\u62e9\u3002\\n\\n## \u7279\u6027\\n\\n- **\u9ad8\u6027\u80fd\u8bfb\u5199**\uff1a\u4e13\u6ce8\u4e8e\u6027\u80fd\u4f18\u5316\uff0c\u80fd\u591f\u9ad8\u6548\u5904\u7406\u5927\u89c4\u6a21\u7535\u5b50\u8868\u683c\u6570\u636e\u3002\u4e0e\u4e00\u4e9b\u4f20\u7edf\u7684\u7535\u5b50\u8868\u683c\u5904\u7406\u5e93\u76f8\u6bd4\uff0c\u5b83\u53ef\u4ee5\u663e\u8457\u51cf\u5c11\u5185\u5b58\u6d88\u8017\u3002\\n- **\u7b80\u5355\u6613\u7528**\uff1a\u8be5\u5e93\u63d0\u4f9b\u4e86\u7b80\u5355\u76f4\u89c2\u7684 API\uff0c\u4f7f\u5f00\u53d1\u8005\u80fd\u591f\u8f7b\u677e\u5c06\u5176\u96c6\u6210\u5230\u9879\u76ee\u4e2d\uff0c\u65e0\u8bba\u662f\u7b80\u5355\u7684\u7535\u5b50\u8868\u683c\u64cd\u4f5c\u8fd8\u662f\u590d\u6742\u7684\u6570\u636e\u5904\u7406\u3002\\n- **\u6d41\u5f0f\u64cd\u4f5c**\uff1a\u652f\u6301\u6d41\u5f0f\u8bfb\u53d6\uff0c\u6700\u5927\u7a0b\u5ea6\u5730\u51cf\u5c11\u4e00\u6b21\u6027\u52a0\u8f7d\u5927\u91cf\u6570\u636e\u7684\u95ee\u9898\u3002\u8fd9\u4e00\u8bbe\u8ba1\u5728\u5904\u7406\u6570\u5341\u4e07\u751a\u81f3\u6570\u767e\u4e07\u884c\u6570\u636e\u65f6\u5c24\u5176\u91cd\u8981\u3002\\n\\n## \u53d1\u5c55\u73b0\u72b6\\n\\n\u9879\u76ee\u7531\u539f\u6838\u5fc3\u7ef4\u62a4\u8005\u4e8e 2024 \u5e74\u53d1\u8d77\uff0c\u65e8\u5728\u63d0\u4f9b\u66f4\u9ad8\u6548\u7684 Excel \u5904\u7406\u89e3\u51b3\u65b9\u6848\uff0c\u5e76\u786e\u4fdd\u957f\u671f\u53ef\u6301\u7eed\u7684\u7ef4\u62a4\u3002\u5f00\u6e90\u4ee5\u6765\u5df2\u521d\u6b65\u5efa\u7acb\u8d77\u4e86\u4e00\u4e2a\u5c0f\u578b\u793e\u533a\uff0c\u4e3b\u4ed3\u5e93\u5728\\nGitHub \u7d2f\u8ba1\u6536\u83b7 **5.0K+** star, \u7d2f\u8ba1\u53d1\u5e03\u793e\u533a\u7248\u672c **5** \u6b21\uff0c\u62e5\u6709 **20+** \u4f4d\u8d21\u732e\u8005\u3002\\n\\n\u6211\u4eec\u9646\u7eed\u6536\u5230\u4e86\u6765\u81ea\u793e\u533a\u7684\u5e7f\u6cdb\u5173\u6ce8\u548c\u652f\u6301\uff0c\u8fd9\u65e2\u662f\u5bf9\u6211\u4eec\u8fc7\u53bb\u5de5\u4f5c\u7684\u8ba4\u53ef\uff0c\u4e5f\u662f\u5bf9\u6211\u4eec\u672a\u6765\u53d1\u5c55\u7684\u671f\u671b\u3002\\n\\n![blog-20250917](/img/blog/20250917-02.png)\\n\\n## \u4e3a\u4f55\u52a0\u5165\u5b75\u5316\u5668\\n\\n\u52a0\u5165 Apache \u5b75\u5316\u5668\u4e3b\u8981\u662f\u57fa\u4e8e\u4ee5\u4e0b\u51e0\u4e2a\u539f\u56e0:\\n\\n- \u5728 Apache \u6210\u719f\u5f00\u6e90\u57fa\u91d1\u4f1a\u7684\u6307\u5bfc\u4e0b, \u8ba9\u5f00\u6e90\u9879\u76ee\u534f\u4f5c\u548c\u793e\u533a\u6cbb\u7406\u8fd0\u8425\u90fd\u66f4\u52a0\u89c4\u8303\u3002\\n- \u6784\u5efa\u66f4\u52a0\u7e41\u8363\u548c\u591a\u6837\u5316\u7684\u5f00\u53d1\u8005\u793e\u533a, \u6211\u4eec\u5e0c\u671b\u53ef\u4ee5\u5438\u5f15\u66f4\u591a\u4f18\u79c0\u7684\u6d77\u5185\u5916\u5f00\u53d1\u8005\u52a0\u5165, \u8ba9\u5f00\u53d1\u8005\u793e\u533a\u66f4\u52a0\u591a\u6837\u5316\u3002\\n- \u6269\u5927\u5e94\u7528\u8303\u56f4\uff0c\u9f13\u52b1\u5c06\u5176\u96c6\u6210\u5230\u66f4\u591a\u5f00\u6e90\u548c\u5546\u4e1a\u9879\u76ee\u4e2d\uff0c\u63a8\u52a8\u65b0\u7684\u7528\u4f8b\u548c\u529f\u80fd\u5f00\u53d1\u3002\\n\\n\u63a5\u4e0b\u6765\u793e\u533a\u4f1a\u5728 Apache \u5b75\u5316\u5668\u5bfc\u5e08\u7684\u5f15\u5bfc\u4e0b, \u9075\u4ece \u201cCommunity over Code\u201d \u7684\u7406\u5ff5\u6765\u7ba1\u7406\u548c\u8fd0\u8425\u793e\u533a,\\n\u4e5f\u8ba9\u6bcf\u4e2a\u4f18\u79c0\u8d21\u732e\u8005\u90fd\u80fd\u591f\u88ab\u770b\u89c1\u3002\u5728\u5f00\u6e90\u4ea7\u54c1\u5c42\u9762\uff0c\u503e\u542c\u7528\u6237\u58f0\u97f3\uff0c\u63d0\u5347\u4f18\u5316\u4ea7\u54c1\u4f7f\u7528\u4f53\u9a8c\uff0c\u6253\u9020\u5bf9\u63a5\u5f00\u6e90\u751f\u6001\u3002\\n\\n## \u5bfc\u5e08\u4ecb\u7ecd\\n\\n- tison(Champion)\\n- Dave Fisher\\n- PJ Fanning\\n- Huajie Wang\\n\\n\u611f\u8c22\u5404\u4f4d\u5bfc\u5e08\u65e0\u79c1\u7684\u5e2e\u52a9, \u5728\u5408\u89c4\u548c\u6d41\u7a0b\u63a8\u8fdb\u4e0a\u7684\u7ed9\u4e88\u4e86\u4e13\u4e1a\u6307\u5bfc\u3002\u7279\u522b\u611f\u8c22\u9879\u76ee\u7684 Champion\\n@tison\uff0c\u5728\u9879\u76ee\u8fdb\u5165\u5b75\u5316\u5668\u7684\u8fc7\u7a0b\u4e2d\u4e3b\u5bfc\u4e86\u9879\u76ee\u4ece\u8349\u6848\u8d77\u8349\u9636\u6bb5\u5230\u8ba8\u8bba\u518d\u5230\u53d1\u8d77\u6295\u7968\u6574\u4e2a\u8fc7\u7a0b,\\n\u7ed9\u4e86\u5f88\u591a\u4e13\u4e1a\u7684\u5efa\u8bae\u548c\u6307\u5bfc\u3002\\n\\n\u76f8\u4fe1\u672a\u6765\u5728\u5404\u4f4d\u5bfc\u5e08\u7684\u6307\u5bfc\u4e0b\u793e\u533a\u4e00\u5b9a\u66f4\u52a0\u5065\u5eb7\u7684\u6210\u957f\u3002\\n\\n## \u52a0\u5165\u6211\u4eec\\n\\n**\u9879\u76ee\u5730\u5740**\\n\\n- <https://github.com/apache/fesod>\\n\\n**\u5b98\u65b9\u7f51\u5740**\\n\\n- <https://fesod.apache.org/>\\n\\n**\u90ae\u4ef6\u5217\u8868**\\n\\n- <dev@fesod.apache.org>"}]}}')}}]);